import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"頤","description":"周易集解 - 頤","frontmatter":{"title":"頤","description":"周易集解 - 頤"},"headers":[],"relativePath":"classics/jijie/027.md","filePath":"classics/jijie/027.md"}'),l={name:"classics/jijie/027.md"};function n(d,a,p,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="頤" tabindex="-1">頤 <a class="header-anchor" href="#頤" aria-label="Permalink to “頤”">​</a></h1><h2 id="頤-1" tabindex="-1">頤 <a class="header-anchor" href="#頤-1" aria-label="Permalink to “頤”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>頤，貞吉。觀頤，自求口實。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《序卦》曰：物畜然後可養，故受之以頤。頤者，養也。</p><p>崔憬曰：大畜剛健，輝光日新，可以觀其所養，故言｢物畜然後可養｣。</p><p>虞翻曰：晉四之初。與大過旁通。養正則吉。謂三爻之正，五上易位，故頤貞吉。反覆不衰，與乾、坤、坎、離、大過、小過、中孚同義。故不從臨觀四陰二陽之例。或以臨二之上，兌為口，故有口實也。</p><p>虞翻曰：離為目，故觀頤，觀其所養也。</p><p>虞翻曰：或以大過兌為口，或以臨兌為口。坤為自，艮為求。口實，頤中物，謂其自養。</p><p>鄭玄曰：頤中，口車輔之名也。震動於下，艮止於上，口車動而上，因輔嚼物以養人，故謂之頤。頤，養也。能行養，則其幹事，故吉矣。二五離爻，皆得中。離為目，觀象也。觀頤，觀其養賢與不肖也。頤中有物曰｢口實｣。自二至五有二坤，坤載養物，而人所食之物皆存焉。觀其求可食之物，則貪廉之情可別也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：頤貞吉，養正則吉也。觀頤，觀其所養也。自求口實，觀其自養也。天地養萬物，聖人養賢以及萬民。頤之時大矣哉。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>《彖》曰：頤貞吉，養正則吉也。</p><p>姚信曰：以陽養陰，動於下，止於上，各得其正，則吉也。</p><p>宋衷曰：頤者，所由飲食自養也。君子割不正不食，況非其食乎。是故所養必得賢明，自求口實，必得體宜，是謂養正也。</p><p>侯果曰：王者所養，養賢則吉也。</p><p>侯果曰：此本觀卦。初六升五，九五降初，則成頤也。是自求口實，觀其自養。</p><p>案：口實，謂頤口中也。實事可言。震，聲也。實物可食。艮，其成也。</p><p>崔玄曰：天，上。地，初也。萬物，眾陰也。天地以元氣養萬物，聖人以正道養賢及萬民，此其聖也。</p><p>虞翻曰：乾為聖人，艮為賢人，頤下養上，故聖人養賢。坤陰為民，皆在震上。以貴下賤，大得民，故以及萬民。</p><p>天地養物，聖人養賢以及萬民，人非頤不生，故大矣。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：山下有雷，頤。君子以慎言語，節飲食。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>劉表曰：山止於上，雷動於下，頤之象也。</p><p>荀爽曰：雷為號令，今在山下閉藏，故慎言語。雷動於上，以陽食陰，艮以止之，故節飲食也。言出乎身，加乎民，故慎言語所以養人也。飲食不節，殘賊群生，故節飲食以養物。</p><h2 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h2><p>初九，舍爾靈龜，觀我朵頤，兇。</p><h2 id="初九注" tabindex="-1">初九注 <a class="header-anchor" href="#初九注" aria-label="Permalink to “初九注”">​</a></h2><p>虞翻曰：晉離為龜，四之初，故舍爾靈龜。艮為我，震為動；謂四失離入坤，遠應多懼，故兇矣。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：觀我朵頤，亦不足貴也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>侯果曰：初本五也。五互體艮，艮為山龜。自五降初，則為頤矣。是｢舍爾靈龜｣之德，來｢觀朵頤｣之饌。貪祿致兇。故不足貴。</p><p>案：朵，頤垂下動之貌也。</p><h2 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h2><p>六二，顛頤，拂經於丘頤，徵兇。</p><h2 id="六二注" tabindex="-1">六二注 <a class="header-anchor" href="#六二注" aria-label="Permalink to “六二注”">​</a></h2><p>王肅曰：養下曰顛。拂，違也。經，常也。丘，小山，謂六五也。二宜應五，反下養初，豈非顛頤，違常於五也，故曰｢拂經於丘｣矣。拂丘雖阻常理，養下故謂養賢。上既無應，徵必兇矣，故曰徵兇。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：六二徵兇，行失類也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>侯果曰：正則失養之類。</p><h2 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h2><p>六三，拂頤，貞兇。十年勿用，無攸利。</p><h2 id="六三注" tabindex="-1">六三注 <a class="header-anchor" href="#六三注" aria-label="Permalink to “六三注”">​</a></h2><p>虞翻曰：三失位體剝，不正相應，弒父弒君，故｢貞兇｣。坤為十年，動無所應，故｢十年勿用，無攸利｣也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：十年勿用，道大悖也。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：弒父弒君，故大悖也。</p><h2 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h2><p>六四，顛頤，吉。虎視眈眈，其欲逐逐，無咎。</p><h2 id="六四注" tabindex="-1">六四注 <a class="header-anchor" href="#六四注" aria-label="Permalink to “六四注”">​</a></h2><p>王弼曰：履得其位，而應於初，以上養下，得頤之義。故曰顛頤吉。下交近瀆，則咎矣。故虎視眈眈，威而不猛。故其欲逐逐，而尚敦實。修此二者，乃得全其吉而無咎矣。觀其自養則養正，察其所養則養賢，頤爻之貴，斯為盛矣。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：顛頤之吉，上施光也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：晉四之初，謂三已變，故顛頤。與屯四乘坎馬同義。坤為虎，離為目。眈眈，下眩貌。逐逐，心煩貌，坤為吝嗇，坎水為欲，故其欲逐逐。得位應初，故無咎。謂上已反三成離，故上施光也。</p><h2 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h2><p>六五，拂經，居貞吉，不可涉大川。</p><h2 id="六五注" tabindex="-1">六五注 <a class="header-anchor" href="#六五注" aria-label="Permalink to “六五注”">​</a></h2><p>虞翻曰：失位，故拂經。無應順上。故居貞吉。艮為居也。涉上成坎，乘陽無應，故不可涉大川矣。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：居貞之吉，順以從上也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>王弼曰：以陰居陽，拂頤之義也。無應於下，而比於上。故宜居貞，順而從上則吉。</p><h2 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h2><p>上九，由頤，厲，吉。利涉大川。</p><h2 id="上九注" tabindex="-1">上九注 <a class="header-anchor" href="#上九注" aria-label="Permalink to “上九注”">​</a></h2><p>虞翻曰：由，自從也。體剝居上，眾陰順承，故由頤。失位，故厲。以坤艮自輔，故吉也。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：由頤，厲吉，大有慶也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：失位，厲危。之五得正成坎，坎為大川，故利涉大川。變陽得位，故大有慶也。</p>',77)])])}const m=e(l,[["render",n]]);export{b as __pageData,m as default};
